-- DROP Table campos_cliente_persona_copy DROP TABLE IF EXISTS campos_cliente_persona_copy; CREATE TABLE campos_cliente_persona_copy ( client_id int8 NOT NULL, "Cedula" varchar(20) NOT NULL, "Estado Civil_cd_Estado civil" int4 NOT NULL, "Edad" int4 NOT NULL, "Estrato" int4 NULL, "Ciudad_cd_Ciudad" int4 NOT NULL, "Tiene vehiculo propio" bool DEFAULT false NULL, "Tipo Vehiculo_cd_Tipo de vehiculo" int4 NULL, "Nivel Academico_cd_Nivel academico" int4 NULL, "Actividad Laboral_cd_Actividad laboral" int4 NULL, "Tiempo de actividad laboral" int4 NULL, "Media de ingresos" numeric(14, 2) NULL, "Nombre empresa" varchar(100) NULL, "Direccion" varchar(200) NOT NULL, "Telefono" varchar(60) NULL, "Cupo solicitado" numeric(19, 2) NULL, "Cupo aprobado" numeric(19, 2) NOT NULL, "Cupo otros prestamos" numeric(19, 2) NOT NULL, "Cupo score" numeric(19, 2) NULL, "Valor score" int4 NULL, "Modelo score" varchar(10) NULL, "Referencia" varchar(60) NOT NULL, "Celular Referencia" varchar(30) NOT NULL, "Parentesco_cd_Parentesco" int4 NOT NULL, created_at timestamp NULL, updated_at timestamp NULL, CONSTRAINT campos_cliente_personaz_pkey PRIMARY KEY (client_id), CONSTRAINT "unique_campos_cliente_personaz_Cedula" UNIQUE ("Cedula") );
-- public.campos_cliente_persona foreign keys ALTER TABLE public.campos_cliente_persona_copy ADD CONSTRAINT fk_campos_cliente_persona_client_id FOREIGN KEY (client_id) REFERENCES m_client(id) ON DELETE CASCADE ON UPDATE RESTRICT;
-- Copy data from campos_cliente_persona to campos_cliente_persona_copy INSERT INTO campos_cliente_persona_copy (client_id, "Cedula", "Estado Civil_cd_Estado civil", "Edad", "Estrato", "Ciudad_cd_Ciudad", "Tiene vehiculo propio", "Tipo Vehiculo_cd_Tipo de vehiculo", "Nivel Academico_cd_Nivel academico", "Actividad Laboral_cd_Actividad laboral", "Tiempo de actividad laboral", "Media de ingresos", "Nombre empresa", "Direccion", "Telefono", "Cupo solicitado", "Cupo aprobado", "Cupo otros prestamos", "Cupo score", "Valor score", "Modelo score", "Referencia", "Celular Referencia", "Parentesco_cd_Parentesco", created_at, updated_at) SELECT client_id, "Cedula", "Estado Civil_cd_Estado civil", "Edad", "Estrato", "Ciudad_cd_Ciudad", "Tiene vehiculo propio", "Tipo Vehiculo_cd_Tipo de vehiculo", "Nivel Academico_cd_Nivel academico", "Actividad Laboral_cd_Actividad laboral", "Tiempo de actividad laboral", "Media de ingresos", "Nombre empresa", "Direccion", "Telefono", "Cupo solicitado", "Cupo aprobado", 0, "Cupo score", "Valor score", "Modelo score", "Referencia", '', "Parentesco_cd_Parentesco", created_at, updated_at FROM campos_cliente_persona;
-- Drop campos_cliente_persona table DROP TABLE campos_cliente_persona;
-- Rename campos_cliente_persona_copy to campos_cliente_persona ALTER TABLE campos_cliente_persona_copy RENAME TO campos_cliente_persona;

-- DROP TABLE campos_cliente_empresas_copy; DROP TABLE IF EXISTS campos_cliente_empresas_copy;
-- CREATE TABLE campos_cliente_empresas_copy CREATE TABLE campos_cliente_empresas_copy ( client_id int8 NOT NULL, "NIT" varchar(20) NOT NULL, "Tipo ID_cd_Tipo ID" int4 NOT NULL, "Regimen IVA_cd_Regimen IVA" int4 NOT NULL, "Direccion" varchar(40) NOT NULL, "Departamento_cd_Departamento" int4 NOT NULL, "Ciudad_cd_Ciudad" int4 NOT NULL, "Telefono" varchar(60) DEFAULT NULL::character varying NULL, "Retencion" varchar(2) NOT NULL, "Cupo" numeric(19, 2) NOT NULL, "Cupo otros prestamos" numeric(19, 2) NOT NULL, "Fecha Cupo" date NOT NULL, "Segmento_cd_Segmento" int4 NOT NULL, "CIIU_cd_CIIU" int4 NOT NULL, "Negocio_cd_Negocio" int4 NOT NULL, "Categoria_cd_Categoria" int4 NOT NULL, "NIT confirming" varchar(15) NULL, "Nombre codeudor 1" varchar(40) DEFAULT NULL::character varying NULL, "Cedula codeudor 1" varchar(20) DEFAULT NULL::character varying NULL, "Rep legal codeudor_cd_Rep legal codeudor 1" int4 NULL, "Nombre codeudor 2" varchar(40) NULL, "Cedula codeudor 2" varchar(20) NULL, "Rep legal codeudor_cd_Rep legal codeudor 2" int4 NULL, "Nombre codeudor 3" varchar(40) NULL, "Cedula codeudor 3" varchar(20) NULL, "Rep legal codeudor_cd_Rep legal codeudor 3" int4 NULL, created_at timestamp NULL, updated_at timestamp NULL, CONSTRAINT campos_cliente_empresasz_pkey PRIMARY KEY (client_id), CONSTRAINT unique_campos_cliente_empresasz_nit UNIQUE ("NIT") );
-- public.campos_cliente_empresas_copy foreign keys ALTER TABLE public.campos_cliente_empresas_copy ADD CONSTRAINT fk_campos_cliente_empresas_client_id FOREIGN KEY (client_id) REFERENCES m_client(id);
-- Copy data from campos_cliente_empresas to campos_cliente_empresas_copy INSERT INTO campos_cliente_empresas_copy ("client_id", "NIT", "Tipo ID_cd_Tipo ID", "Regimen IVA_cd_Regimen IVA", "Direccion", "Departamento_cd_Departamento", "Ciudad_cd_Ciudad", "Telefono", "Retencion", "Cupo", "Cupo otros prestamos", "Fecha Cupo", "Segmento_cd_Segmento", "CIIU_cd_CIIU", "Negocio_cd_Negocio", "Categoria_cd_Categoria", "NIT confirming", "Nombre codeudor 1", "Cedula codeudor 1", "Rep legal codeudor_cd_Rep legal codeudor 1", "Nombre codeudor 2", "Cedula codeudor 2", "Rep legal codeudor_cd_Rep legal codeudor 2", "Nombre codeudor 3", "Cedula codeudor 3", "Rep legal codeudor_cd_Rep legal codeudor 3", "created_at", "updated_at") SELECT "client_id", "NIT", "Tipo ID_cd_Tipo ID", "Regimen IVA_cd_Regimen IVA", "Direccion", "Departamento_cd_Departamento", "Ciudad_cd_Ciudad", "Telefono", "Retencion", "Cupo", 0, "Fecha Cupo", "Segmento_cd_Segmento", "CIIU_cd_CIIU", "Negocio_cd_Negocio", "Categoria_cd_Categoria", "NIT confirming", "Nombre codeudor 1", "Cedula codeudor 1", "Rep legal codeudor_cd_Rep legal codeudor 1", "Nombre codeudor 2", "Cedula codeudor 2", "Rep legal codeudor_cd_Rep legal codeudor 2", "Nombre codeudor 3", "Cedula codeudor 3", "Rep legal codeudor_cd_Rep legal codeudor 3", "created_at", "updated_at" FROM campos_cliente_empresas;
-- Drop campos_cliente_empresas table DROP TABLE campos_cliente_empresas;
